  if (jsonPart) {
    try {
      const parsed = JSON.parse(jsonPart[0].replace(/\\"/g, '"'));
      const msg = parsed.detail || parsed.message || parsed.error;
      if (msg) return String(msg).slice(0, 300);
    } catch (e) { /* fall through to raw */ }
  }
  return raw.slice(0, 300);
};

const providerStatus = String(resp.status || '').toLowerCase();
const failed = isError || providerStatus === 'failed' || resp.ok === false;

const errorDetail = isError
  ? humanError(incoming.error)
  : (failed ? String(resp.error || resp.detail || 'Provider reported a failure').slice(0, 300) : '');

const payload = {
  provider: 'voicebip',
  channel: 'sms',
  direction: 'outbound',
  status: failed ? 'failed' : 'sent',
  patient_name: base.patient_name || '',
  patient_phone: base.patient_phone || '',
  request_code: base.request_id || '',
  external_ref: failed ? '' : (resp.external_ref || resp.message_id || resp.id || resp.call_id || ''),
  summary: 'Appointment options sent via SMS',
  error_detail: errorDetail,
};

let logged = { ok: false };
try {
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: $env.DJANGO_API_BASE_URL + '/interactions/',
    headers: { 'Content-Type': 'application/json', 'X-Webhook-Secret': $env.DJANGO_WEBHOOK_SECRET || '' },
    body: payload,
    json: true,
  });
  logged = { ok: true, id: res.id, status: res.status };
} catch (e) {
  logged = { ok: false, error: (e.message || String(e)).slice(0, 300) };
}

return [{ json: { ...base, provider_response: resp, interaction_log: { ...logged, payload } } }];

