try {
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: $env.DJANGO_API_BASE_URL + '/interactions/',
    headers: { 'Content-Type': 'application/json', 'X-Webhook-Secret': $env.DJANGO_WEBHOOK_SECRET || '' },
    body: payload,
    json: true,
  });
  logged = { ok: true, id: res.id, status: res.status };
} catch (e) {
  logged = { ok: false, error: (e.message || String(e)).slice(0, 300) };
}

return [{ json: { ...base, provider_response: resp, interaction_log: { ...logged, payload } } }];

// Phase 0 — the dispatch webhook is the only n8n entry point that can make the
// clinic send real messages and place real calls, so it is authenticated before
// anything else runs. Fail closed: an unset DJANGO_WEBHOOK_SECRET rejects every
// request (an unconfigured receiver never accepts traffic).
//
// Django sends the same value it uses for every X-Webhook-Secret call
// (ClinicSetting.webhook_secret -> settings.WEBHOOK_SECRET -> dev fallback).
const src = $input.first().json || {};
const headers = src.headers || {};

const env = (name) => { try { const v = $env[name]; return v == null ? '' : String(v); } catch (e) { return ''; } };

const expected = env('DJANGO_WEBHOOK_SECRET');
const provided = String(headers['x-webhook-secret'] || '').trim();
const authorized = Boolean(expected) && provided === expected;

return [{ json: {
  ...src,
  dispatch_auth: {
    authorized: authorized,
    reason: authorized ? null : (expected ? 'bad_secret' : 'secret_not_configured'),
  },
} }];
